"""Measured opt-in roster preparation (generalised from prepare-lou-roster.py).

  python3 tools/wrestler-cutter/prepare-roster-character.py <george|kowalski|guido>

Source PSD/full-canvas exports are never modified. Landmarks marked MANUAL are
reviewable judgments read off gridded full-canvas renders, not certified anatomy.
"""
import sys
from pathlib import Path
from PIL import Image
import numpy as np
import math,json

CONFIG_TMPL="""// Opt-in %(label)s PSD comparison. Generated by prepare-roster-character.py %(arg)s.
// Source authority and measurements: Sprite sheets/RosterNew/2026-10-18/%(dir)s/
// extracted-v1/cleaned-v1/comparison-v1/measurements.json.
// %(note)s Manual source landmarks require visual review.
import { %(base)s } from './%(basefile)s.js';
export const %(const)s = {
    id: '%(id)s', skinCol: %(base)s.skinCol, trunksCol: %(base)s.trunksCol,
    idlePose: %(base)s.idlePose, tauntPose: %(base)s.tauntPose, begsOff: %(base)s.begsOff, struts: %(base)s.struts,
    sellStyle: %(base)s.sellStyle, moveSet: %(base)s.moveSet,
    textures: @@TEXTURES@@,
};
export const %(snake)s = %(const)s;
"""
# Layer A/B names are not anatomical. Pairs come from measured thigh/shin overlap. The thigh that paints
# on top in the PSD composite (thigh_b) is the FRONT/near leg; thigh_a is the BACK/far leg. Derek edited
# the back legs, so both legs are used (farThigh/farShin), not one shared pair.
import os
KNEELIFT=float(os.environ.get('KNEELIFT',22))
SPECS={
 'george':dict(dir='GeorgeNew',forearmGrip=dict(key='george_rv1_forearm_grip',file='forearm_grip.png',semanticAnchors=dict(clutch=dict(u=254/426,v=344/439))),id='george-roster-v1',prefix='george_rv1_',snake='george_roster_v1',heightScale=1.012010,kneeLift=KNEELIFT,forearmOverUpperArm=True,farLegOverTorso=True,
  # Derek 2026-10-25 (PLAN_GEORGE_TRANSFER G6a) picked candidate C (6 game px inside the back contour at the top of the trunks);
  # Rev 2 D6 (after G6: C is on the visible belly supine) moved it to candidate A, ON the contour, with the hand drawn under the
  # body (backSell handUnder). tools/debug/backwaist_candidates.mjs, research/animation/george-transfer-2026-10/backwaist/. Torso-canvas fractions.
  backWaist={'u':0.2558,'v':0.6077},
  # Measured with tools/debug/{hold_weight_sweep,recovery_probe}.mjs on this rig (PLAN_GEORGE_TRANSFER T3.2/T3.3, re-measured at anchor A in T6.4); fist art only, so the contact is the wrist proxy.
  backSell={'holdW':0.7,'recoveryArm':-0.7,'recoveryElbow':1.1,'settledElbow':0.7,'contactPx':15,'handUnder':True,'aroundVia':{'u':-0.25,'v':0.9069,'recoveryArm':-0.6,'recoveryElbow':-0.4,'approach':0.4},'evidence':'Re-measured at backWaist candidate A (u .2558, v .6077, on the contour) at 2026-10-25, PLAN_GEORGE_TRANSFER T6.4: tools/debug/hold_weight_sweep.mjs (holdW .45, fist wrist proxy, constant weight, first weight within 15 px at every sampled offset of the hold cycle .43 both facings, at .45 worst 14.35 px / rest 13.99 px); tools/debug/recovery_probe.mjs (arm -0.7 / elbow +1.1, wrist proxy 1.94 px both facings, flex 103.1 deg, limit 157.6); contactPx 15 kept (wrist proxy, no grip donor); handUnder: the forearm draws behind the torso while the grip latch is on; holdW .45 -> .7 at T8.3 (the route through aroundVia is longer than the straight path, tools/debug/hold_weight_sweep.mjs now: first weight within 15 px at every sampled offset .695 both facings, at .7 worst 14.52 px, margin .48 px; dist at w .5/.6/.7/.8/.9/1 = 24.2 / 19.36 / 14.52 / 9.68 / 4.84 / 0); aroundVia: tools/debug/around_via_candidates.mjs candidate B (Derek G8a, 1.5 hand lengths = 32.4 game px from backWaist, 18.0 px clear of the paint; recoveryArm -0.6 / recoveryElbow -0.4: tools/debug/around_recovery_probe.mjs, wrist 8.03 px from the via point on both facings, hand clear by 16.0 px; approach .4: the reach of a back clutch takes .4 of the clutch to get in instead of .25, tools/debug/route_probe.mjs, so the longer route keeps the move of the wrist relative to the back waist <= 2.21 px per frame)'},
  heightNote='heightScale set by matching rig-tuner idle ink height at zoom 1.4 (facing 1) to current George: 335.3805 vs 332.87 at scale 1.00445 (after the 22px shin pivot lift); uniform, no per-part adjustment.',
  alias={'thigh_b':'right_thigh','shin_a':'right_shin','thigh_a':'left_thigh','shin_b':'left_shin','upper_arm':'right_upper_arm','forearm_hand':'right_forearm_hand'},
  shoulder=[1080,420],farshoulder=[1255,425],wrist=[1095,800],ankle=[1068,1425],sole=[1105,1565],farankle=[1262,1425],farsole=[1295,1550],
  cfg=dict(label='GeorgeNew',arg='george',dir='GeorgeNew',base='george',basefile='george',const='georgeRosterV1',id='george-roster-v1',snake='george_roster_v1',note='Current George remains unchanged.')),
 'kowalski':dict(dir='Killer_Kowalski',
  # Derek 2026-10-20: far shoulder lower+back, same pixels as Guido's (-3,+4 px)
  socketNudge={'farShoulder':(-0.0522,0.0366)},id='kowalski-roster-v1',prefix='kowalski_rv1_',snake='kowalski_roster_v1',heightScale=0.942960,kneeLift=KNEELIFT,forearmOverUpperArm=True,farLegOverTorso=True,
  heightNote='PLACEHOLDER: matched to current Procreate Lou ink height (347.79 vs 370.27 at scale 1, tuner zoom 1.4; re-matched after the knee lift); Kowalski is meant to be taller, so Derek should set the intended ratio.',
  alias={'thigh_b':'right_thigh','shin_b':'right_shin','thigh_a':'left_thigh','shin_a':'left_shin','upper_arm':'right_upper_arm','forearm_hand':'right_forearm_hand'},
  shoulder=[325,345],farshoulder=[520,355],wrist=[285,810],ankle=[285,1530],sole=[310,1660],farankle=[510,1530],farsole=[535,1650],
  cfg=dict(label='Killer_Kowalski',arg='kowalski',dir='Killer_Kowalski',base='thesz',basefile='thesz',const='kowalskiRosterV1',id='kowalski-roster-v1',snake='kowalski_roster_v1',note='Kowalski has no shipped config; kit and pose are borrowed from Lou (thesz) as a neutral control.')),
 'guido':dict(dir='GuidoNew',id='guido-roster-v1',prefix='guido_rv1_',snake='guido_roster_v1',heightScale=1.003380,headOverTorso=True,
  # Derek 2026-10-20: near shoulder a little down+forward, far shoulder a little lower+back (du,dv in torso-canvas fractions)
  socketNudge={'nearShoulder':(0.057,0.032),'farShoulder':(-0.057,0.043)},
  heightNote='PLACEHOLDER: matched to current George ink height (335.38 vs 334.25 at scale 1, tuner zoom 1.4) (Guido is meant to be compact; Derek should set the intended ratio).',
  alias={'thigh_b':'right_thigh','shin_b':'right_shin','thigh_a':'left_thigh','shin_a':'left_shin','upper_arm':'right_upper_arm','forearm_hand_taped':'right_forearm_hand'},
  shoulder=[1060,415],farshoulder=[1295,420],wrist=[1020,810],ankle=[1072,1440],sole=[1110,1565],farankle=[1262,1440],farsole=[1300,1535],
  cfg=dict(label='GuidoNew',arg='guido',dir='GuidoNew',base='george',basefile='george',const='guidoRosterV1',id='guido-roster-v1',snake='guido_roster_v1',note='Guido has no shipped config; kit and pose are borrowed from George as a neutral control. LIMITATION: only ONE forearm (taped wrist) was supplied, so both forearms use it until an untaped counterpart is supplied.')),
}
ROOT=Path(__file__).resolve().parents[2]
SPEC=SPECS[sys.argv[1]]
SOURCE=ROOT/'Sprite sheets/RosterNew/2026-10-18'/SPEC['dir']/'extracted-v1/cleaned-v1/layers-full-canvas'
OUT=ROOT/'src/assets/wrestlers'/SPEC['id'];OUT.mkdir(parents=True,exist_ok=True)
EVIDENCE=SOURCE.parent/'comparison-v1';EVIDENCE.mkdir(exist_ok=True)
ALIAS=SPEC['alias']
images={ALIAS.get(n,n):Image.open(p).convert('RGBA') for p in SOURCE.glob('*.png') for n in [p.name.split('-',1)[1][:-4]]}
def overlap(a,b):
 y,x=np.where((np.array(images[a].getchannel('A'))>=128)&(np.array(images[b].getchannel('A'))>=128));return [float(x.mean()),float(y.mean())]
neck=overlap('head','torso');elbow=overlap('right_upper_arm','right_forearm_hand');hip=overlap('right_thigh','torso');farhip=overlap('left_thigh','torso');knee=overlap('right_thigh','right_shin');farknee=overlap('left_thigh','left_shin')
# Shoulder joints lie in the deltoid cap, not the centroid of the long torso overlap.
# Ankle is the anatomical heel/ankle region, not the cuff or projected toe mass.
# These visible-landmark placements are initial measurement judgments for tuner review.
shoulder,farshoulder,wrist,ankle,sole,farankle,farsole=[list(map(float,SPEC[n])) for n in ['shoulder','farshoulder','wrist','ankle','sole','farankle','farsole']]
anchors=dict(neck=neck,nearShoulder=shoulder,farShoulder=farshoulder,elbow=elbow,wrist=wrist,nearHip=hip,farHip=farhip,knee=knee,ankle=ankle,sole=sole,farKnee=farknee,farAnkle=farankle,farSole=farsole)
HEIGHT_SCALE=SPEC['heightScale'];k=.16;parts={};records={}
def prepare(name,source,prox=None,dist=None):
 im=images[source];bbox=im.getchannel('A').getbbox();box=(bbox[0]-12,bbox[1]-12,bbox[2]+12,bbox[3]+12);im=im.crop(box)
 local=lambda p:[p[0]-box[0],p[1]-box[1]]
 angle=0;offset=[0,0]
 if prox is not None and dist is not None:
  p=local(prox);q=local(dist);angle=math.atan2(q[0]-p[0],q[1]-p[1]);c,s=math.cos(angle),math.sin(angle)
  corners=[(c*x-s*y,s*x+c*y) for x,y in [(0,0),(im.width,0),(0,im.height),(im.width,im.height)]]
  lo=[math.floor(min(t[i] for t in corners))-8 for i in [0,1]];hi=[math.ceil(max(t[i] for t in corners))+8 for i in [0,1]]
  im=im.transform((hi[0]-lo[0],hi[1]-lo[1]),Image.Transform.AFFINE,(c,s,c*lo[0]+s*lo[1],-s,c,-s*lo[0]+c*lo[1]),Image.Resampling.BICUBIC)
  def transport(v):
   x,y=local(v);return [c*x-s*y-lo[0],s*x+c*y-lo[1]]
 else:
  transport=local
 if prox is not None:
  px=transport(prox)[0];half=math.ceil(max(px,im.width-px));shift=half-px
  # Integer canvas shift preserves decoded pixels; half-pixel residual is
  # represented by the explicit two-anchor binding, not a pose-only offset.
  left=round(shift);expanded=Image.new('RGBA',(2*half,im.height));expanded.paste(im,(left,0));im=expanded
  before=transport
  transport=lambda v,fn=before,dx=left:[fn(v)[0]+dx,fn(v)[1]]
 im.save(OUT/f'{name}.png');w,h=im.size
 rec=dict(source=source,source_crop=list(box),rotation_degrees=math.degrees(angle),canvas=[w,h])
 entry={'key':SPEC['prefix']+name}
 if prox is not None:
  p=transport(prox);q=transport(dist);j=p[1]/h;scale=math.dist(prox,dist)*k/math.dist(p,q)
  entry.update(box={'w':w*scale*(1-j),'h':h*scale*(1-j)},jointPivotFrac=j,pivotOffsetFrac=p[0]/w-.5,distalAnchorFrac={'u':q[0]/w,'v':q[1]/h})
  entry['binding']={'proximal':{'u':p[0]/w,'v':p[1]/h},'distal':{'u':q[0]/w,'v':q[1]/h}}
  rec.update(proximal=p,distal=q,bone_length=math.dist(prox,dist)*k)
  if name.endswith('shin'):
   t=transport(farsole if name=='far_shin' else sole);entry['soleAnchorFrac']={'u':t[0]/w,'v':t[1]/h};rec['sole']=t
 else:entry['box']={'w':w*k,'h':h*k}
 parts[name]=entry;records[name]=rec
 return transport,im.size
th,headsize=prepare('head','head');tt,ts=prepare('torso','torso');prepare('upper_arm','right_upper_arm',shoulder,elbow);prepare('forearm','right_forearm_hand',elbow,wrist);prepare('thigh','right_thigh',hip,knee)
def lifted(k,a,d):
 # Shin pivot placed d source-px up the shin painting (toward its top edge): the calf hangs lower
 # and its top corners stay under the thigh when the knee bends. The thigh keeps the true knee.
 v=[a[0]-k[0],a[1]-k[1]];n=math.hypot(*v);return [k[0]-v[0]/n*d,k[1]-v[1]/n*d]
KL=SPEC.get('kneeLift',0)
prepare('shin','right_shin',lifted(knee,ankle,KL),ankle);prepare('far_thigh','left_thigh',farhip,farknee);prepare('far_shin','left_shin',lifted(farknee,farankle,KL),farankle)
sockets={n:{'u':tt(anchors[n])[0]/ts[0],'v':tt(anchors[n])[1]/ts[1]} for n in ['neck','nearShoulder','farShoulder','nearHip','farHip']}
for _n,(_du,_dv) in SPEC.get('socketNudge',{}).items():sockets[_n]['u']+=_du;sockets[_n]['v']+=_dv
# The head renderer uses a 68:85 display aspect; pad source to that ratio rather
# than stretching the painted head. Anchor is transported through padding.
head=Image.open(OUT/'head.png');neww=math.ceil(head.height*.8);pad=max(0,(neww-head.width)//2)
if pad:
 expanded=Image.new('RGBA',(neww,head.height));expanded.paste(head,(pad,0));expanded.save(OUT/'head.png');head=expanded
headanchor=th(neck);headanchor[0]+=pad
textures=dict(lockLimbJoints=True,heightScale=HEIGHT_SCALE,nearShinScale=1,farShinScale=1,farThighScale=1,
 torsoH=(sum(p[1] for p in [hip,farhip])/2-neck[1])*k,upperArmH=math.dist(shoulder,elbow)*k,forearmH=math.dist(elbow,wrist)*k,thighH=math.dist(hip,knee)*k,shinH=math.dist(knee,ankle)*k,
 neckInTorso=True,head=SPEC['prefix']+'head',headScale=head.height*k/85,headAnchorFrac={'u':headanchor[0]/head.width,'v':headanchor[1]/head.height},headOffsetX=0,headOffsetY=0,armOffsetX=0,armOffsetY=0,
 nearShinOffsetX=0,nearShinOffsetY=0,farShinOffsetX=0,farShinOffsetY=0,shinUnderThigh=True,handInForearm=True,rigProfile={'sockets':sockets})
if SPEC.get('forearmOverUpperArm'):textures['forearmOverUpperArm']=True
if SPEC.get('farLegOverTorso'):textures['farLegOverTorso']=True
if SPEC.get('headOverTorso'):textures['headOverTorso']=True
textures.update(torso=parts['torso'],upperArm=parts['upper_arm'],forearm=parts['forearm'],thigh=parts['thigh'],shin=parts['shin'],farThigh=parts['far_thigh'],farShin=parts['far_shin'])
if SPEC.get('backWaist'):textures['torso']=dict(textures['torso'],semanticAnchors={'backWaist':SPEC['backWaist']})  # the back sell's anchor; backSell (below) is its measured data
if SPEC.get('backSell'):textures['backSell']=dict(SPEC['backSell'])
if SPEC.get('forearmGrip'):textures['variants']={'forearm':{'grip':dict(SPEC['forearmGrip'])}}  # grip donor art (PLAN_GEORGE_TRANSFER T5.2); the clutch anchor is the back sell's painted contact
report={'height_scale_note':SPEC['heightNote'], 'source':SPEC['dir']+'.psd','units_per_source_pixel':k,'anchorsCanvasPx':anchors,'measurement_methods':{'paired_overlap':'alpha >=128 intersection centroid, recomputed from this PSD','shoulders':'manual deltoid/socket landmark, not long overlap centroid','wrist_ankle_sole':'manual anatomical landmarks; tuner review pending'},'parts':records,'textures':textures}
(EVIDENCE/'measurements.json').write_text(json.dumps(report,indent=2)+'\n')
config=CONFIG_TMPL%SPEC['cfg']
config=config.replace('@@TEXTURES@@',json.dumps(textures,indent=4))
(ROOT/'src/characters'/(SPEC['snake']+'.js')).write_text(config)
print(json.dumps({n:round(textures[n],2) for n in ['torsoH','upperArmH','forearmH','thighH','shinH','headScale']}))
